import{_ as o,o as t,c as a,f as i}from"./chunks/framework.o8v22TzC.js";const u=JSON.parse('{"title":"Privacy Policy | Scroll Tome","description":"Privacy Policy for Scroll Tome — how we handle data, cookies, and third-party services.","frontmatter":{"layout":"privacy","title":"Privacy Policy | Scroll Tome","description":"Privacy Policy for Scroll Tome — how we handle data, cookies, and third-party services.","head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://scrolltome.com/privacy"}]]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),r={name:"privacy.md"};function s(n,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<p>Welcome to <strong>Scroll Tome</strong> (&quot;we&quot;, &quot;our&quot;, or &quot;us&quot;), accessible at <a href="https://scrolltome.com" target="_blank" rel="noreferrer">scrolltome.com</a>. This Privacy Policy explains how we collect, use, and protect information when you visit our website.</p><h2 id="_1-information-we-collect" tabindex="-1">1. Information We Collect <a class="header-anchor" href="#_1-information-we-collect" aria-label="Permalink to &quot;1. Information We Collect&quot;">​</a></h2><p>We do not directly collect personal information such as your name or email address. However, third-party services integrated into this site may collect certain data automatically, including:</p><ul><li>IP address and approximate geographic location</li><li>Browser type and version</li><li>Pages visited and time spent on site</li><li>Referring website or search query</li></ul><h2 id="_2-cookies" tabindex="-1">2. Cookies <a class="header-anchor" href="#_2-cookies" aria-label="Permalink to &quot;2. Cookies&quot;">​</a></h2><p>This site uses cookies through third-party advertising and analytics providers. Cookies are small text files stored on your device. They are used to:</p><ul><li>Serve relevant advertisements based on your browsing interests</li><li>Measure site traffic and usage patterns</li><li>Improve the performance and content of the site</li></ul><p>You can disable cookies in your browser settings at any time. Note that disabling cookies may affect the functionality of some features on this site.</p><h2 id="_3-google-adsense" tabindex="-1">3. Google AdSense <a class="header-anchor" href="#_3-google-adsense" aria-label="Permalink to &quot;3. Google AdSense&quot;">​</a></h2><p>We use <strong>Google AdSense</strong> to display advertisements on this site. Google uses cookies to serve ads based on your prior visits to this website or other websites. You may opt out of personalized advertising by visiting <a href="https://www.google.com/settings/ads" target="_blank" rel="noreferrer">Google Ads Settings</a>.</p><p>Google&#39;s use of advertising cookies enables it and its partners to serve ads based on your visit to this site and/or other sites on the Internet. For more information, see <a href="https://policies.google.com/technologies/ads" target="_blank" rel="noreferrer">Google&#39;s advertising policies</a>.</p><h2 id="_4-google-analytics" tabindex="-1">4. Google Analytics <a class="header-anchor" href="#_4-google-analytics" aria-label="Permalink to &quot;4. Google Analytics&quot;">​</a></h2><p>We may use Google Analytics to understand how visitors interact with our site. Google Analytics collects anonymized data including page views, session duration, and traffic sources. You can opt out via the <a href="https://tools.google.com/dlpage/gaoptout" target="_blank" rel="noreferrer">Google Analytics opt-out browser add-on</a>.</p><h2 id="_5-third-party-links" tabindex="-1">5. Third-Party Links <a class="header-anchor" href="#_5-third-party-links" aria-label="Permalink to &quot;5. Third-Party Links&quot;">​</a></h2><p>Our articles may contain links to external websites. We are not responsible for the privacy practices or content of those sites. We encourage you to review the privacy policies of any third-party sites you visit.</p><h2 id="_6-children-s-privacy" tabindex="-1">6. Children&#39;s Privacy <a class="header-anchor" href="#_6-children-s-privacy" aria-label="Permalink to &quot;6. Children&#39;s Privacy&quot;">​</a></h2><p>This site is not directed at children under the age of 13. We do not knowingly collect personal information from children. If you believe a child has provided us with personal information, please contact us so we can take appropriate action.</p><h2 id="_7-changes-to-this-policy" tabindex="-1">7. Changes to This Policy <a class="header-anchor" href="#_7-changes-to-this-policy" aria-label="Permalink to &quot;7. Changes to This Policy&quot;">​</a></h2><p>We may update this Privacy Policy from time to time. Changes will be reflected by updating the &quot;Last updated&quot; date at the top of this page. Continued use of the site after changes constitutes your acceptance of the updated policy.</p><h2 id="_8-contact" tabindex="-1">8. Contact <a class="header-anchor" href="#_8-contact" aria-label="Permalink to &quot;8. Contact&quot;">​</a></h2><p>If you have any questions about this Privacy Policy, you can reach us via the contact information listed on our website.</p>',21)])])}const y=o(r,[["render",s]]);export{u as __pageData,y as default};
